WITH flattened AS (SELECT id, created_at, EXPLODE(coupon_codes) AS tag FROM carts) SELECT DATE_TRUNC('HOUR', created_at) AS hour_window, COUNT(DISTINCT id) AS distinct_ids, SORT_ARRAY(COLLECT_SET(tag)) AS tag_list, COUNT(*) FILTER (WHERE tag = 'SPRING10') AS spring10_rows, COUNT_IF(tag = 'SPRING10') AS spring10_events, COUNT(DISTINCT tag) AS distinct_tags FROM flattened GROUP BY DATE_TRUNC('HOUR', created_at) ORDER BY distinct_ids DESC;
